PGVECTOR_SCHEMA='''create extension if not exists vector;
create table if not exists documents (id uuid primary key,source_type text not null,filename text,source_url text,text_content text not null,page_count integer,character_count integer not null,status text not null,document_type text,summary jsonb default '{}'::jsonb,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists clauses (id uuid primary key,document_id uuid references documents(id) on delete cascade,position integer not null,clause_number text,title text,text text not null,page_start integer,page_end integer);
create table if not exists law_chunks (id uuid primary key,act_name text not null,section_number text not null,section_title text not null,statutory_text text not null,jurisdiction text not null,source_url text not null,embedding vector(768) not null,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists document_analyses (document_id uuid primary key references documents(id) on delete cascade,analysis jsonb not null);
create or replace function match_law_chunks(query_embedding vector(768),match_count int) returns table(id uuid,act_name text,section_number text,section_title text,statutory_text text,jurisdiction text,source_url text,metadata jsonb,similarity float) language sql stable as $$ select id,act_name,section_number,section_title,statutory_text,jurisdiction,source_url,metadata,1-(embedding <=> query_embedding) from law_chunks order by embedding <=> query_embedding limit match_count; $$;'''
